async function api(path,method='GET',body){const options={method,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(30000),headers:{'X-Requested-With':'XMLHttpRequest'}};if(method!=='GET'){options.headers['Content-Type']='application/json';options.headers['X-CSRF-Token']=account.csrfToken;options.body=JSON.stringify(body);}const response=await fetch(base+'ehr/api/'+path,options),result=await response.json().catch(()=>({}));if(!response.ok||result.code!==0)throw Error(result.msg||result.message||'请求未完成，请刷新后重试');return result.data;}
async function save(change){const previous=structuredClone(state);try{change();const payload={...state,alerts:state.alerts.filter(r=>r.origin!=='legacy')};state=await api('intervention/state','PUT',payload);state.alerts.push(...legacyAlerts);}catch(error){state=previous;throw error;}}
function show(title,html){if(dialog)dialog.close();const d=document.createElement('dialog');dialog=d;d.className='ec-dialog hi-dialog';d.innerHTML='<header><h2>'+e(title)+'</h2><button type="button" aria-label="关闭">×</button></header><div class="ec-dialog-body">'+html+'</div>';document.body.append(d);d.querySelector('header button').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();if(dialog===d)dialog=null;},{once:true});d.showModal();return d;}
