const field=(key,title,value='',type='text',required=false)=>'<label>'+e(title)+'<input name="'+key+'" type="'+type+'" value="'+e(value??'')+'" maxlength="'+(key==='title'?120:255)+'" '+(required?'required':'')+'></label>';
const select=(key,title,options,value='')=>'<label>'+e(title)+'<select name="'+key+'">'+Object.entries(options).map(([k,v])=>'<option value="'+e(k)+'" '+(k===value?'selected':'')+'>'+e(v)+'</option>').join('')+'</select></label>';
const area=(key,title,value='',required=false)=>'<label class="wide">'+e(title)+'<textarea name="'+key+'" maxlength="12000" rows="4" '+(required?'required':'')+'>'+e(value)+'</textarea></label>';
